window.ScripturaLexicons.BDAG_PART_0360 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-01\" data-source=\"BDAG\" data-search=\"τοκετός, οῦ, ὁ substantivo masculino parto; dar à luz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοκετός, οῦ, ὁ</td><td>substantivo masculino</td><td>parto; dar à luz</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-02\" data-source=\"BDAG\" data-search=\"τόκος, ου, ὁ substantivo masculino juros BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τόκος, ου, ὁ</td><td>substantivo masculino</td><td>juros</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-03\" data-source=\"BDAG\" data-search=\"τόλμα, ης, ἡ substantivo feminino audácia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τόλμα, ης, ἡ</td><td>substantivo feminino</td><td>audácia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-04\" data-source=\"BDAG\" data-search=\"τολμάω verbo ousar; atrever-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τολμάω</td><td>verbo</td><td>ousar; atrever-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-05\" data-source=\"BDAG\" data-search=\"τολμηρός, ά, όν adjetivo ousado; audaz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τολμηρός, ά, όν</td><td>adjetivo</td><td>ousado; audaz</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-06\" data-source=\"BDAG\" data-search=\"τολμηροτέρως advérbio remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τολμηροτέρως</td><td>advérbio</td><td>remissão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-07\" data-source=\"BDAG\" data-search=\"τολμητής, οῦ, ὁ substantivo masculino pessoa ousada; audaz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τολμητής, οῦ, ὁ</td><td>substantivo masculino</td><td>pessoa ousada; audaz</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-08\" data-source=\"BDAG\" data-search=\"τομός, ή, όν adjetivo cortante; afiado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τομός, ή, όν</td><td>adjetivo</td><td>cortante; afiado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-09\" data-source=\"BDAG\" data-search=\"τόνος, ου, ὁ substantivo masculino força; tensão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τόνος, ου, ὁ</td><td>substantivo masculino</td><td>força; tensão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-10\" data-source=\"BDAG\" data-search=\"τόξον, ου, τό substantivo neutro arco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τόξον, ου, τό</td><td>substantivo neutro</td><td>arco</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-11\" data-source=\"BDAG\" data-search=\"τοξότης, ου, ὁ substantivo masculino arqueiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοξότης, ου, ὁ</td><td>substantivo masculino</td><td>arqueiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-12\" data-source=\"BDAG\" data-search=\"τοπάζιον, ου, τό substantivo neutro topázio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοπάζιον, ου, τό</td><td>substantivo neutro</td><td>topázio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-13\" data-source=\"BDAG\" data-search=\"τοποθεσία, ας, ἡ substantivo feminino disposição; posicionamento BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοποθεσία, ας, ἡ</td><td>substantivo feminino</td><td>disposição; posicionamento</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-14\" data-source=\"BDAG\" data-search=\"τόπος, ου, ὁ substantivo masculino lugar; região; cargo; oportunidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τόπος, ου, ὁ</td><td>substantivo masculino</td><td>lugar; região; cargo; oportunidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-15\" data-source=\"BDAG\" data-search=\"τοσοῦτος, αύτη, οῦτον adjetivo correlativo tanto; tão grande BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοσοῦτος, αύτη, οῦτον</td><td>adjetivo correlativo</td><td>tanto; tão grande</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-16\" data-source=\"BDAG\" data-search=\"τότε advérbio então; naquele tempo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τότε</td><td>advérbio</td><td>então; naquele tempo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-17\" data-source=\"BDAG\" data-search=\"τοὐναντίον expressão remissiva remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοὐναντίον</td><td>expressão remissiva</td><td>remissão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-18\" data-source=\"BDAG\" data-search=\"τοὔνομα expressão remissiva remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοὔνομα</td><td>expressão remissiva</td><td>remissão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-19\" data-source=\"BDAG\" data-search=\"τοὐπίσω expressão remissiva remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τοὐπίσω</td><td>expressão remissiva</td><td>remissão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0360-20\" data-source=\"BDAG\" data-search=\"τουτέστιν expressão remissiva remissão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τουτέστιν</td><td>expressão remissiva</td><td>remissão</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0360-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοκετός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοκετός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (de <span class=\"greek\">τίκτω</span> por intermédio de <span class=\"greek\">τόκος</span>; Aristot. et al.; BGU 665 II, 10 [I d.C.]; Sb 5873, 4; LXX; Jos., Ant. 1, 213) parto, dar à luz IEph 19:1. Em linguagem figurada dos tormentos do martírio <span class=\"greek\">ὁ</span> <span class=\"greek\">τοκετός</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἐπίκειται</span> as dores do parto estão sobre mim IRo 6:1.—DELG s.v. <span class=\"greek\">τίκτω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόκος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τόκος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">τίκτω</span>; Hom. et al. no sentido de ‘descendência’ etc.) juros sobre dinheiro emprestado (Pind., Pla. et al.; inscrições, papiros, LXX, Philo; Jos., C. Ap. 2, 208; Ath. 30, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:23</a> (PLond II, 218, 4 p. 15 [III a.C.] <span class=\"greek\">ἐδάνεισεν</span> <span class=\"greek\">σὺν</span> <span class=\"greek\">τόκῳ</span>). <span class=\"greek\">τόκοι</span> <span class=\"greek\">τόκων</span> juros compostos (Aristoph., Nub. 1156 al.) ApcPt 16:31.—JHerrmann, Zinssätze usw. [papiros greco-egípcios], JJP 14, ’62, 23–31. B. 800.—DELG s.v. <span class=\"greek\">τίκτω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόλμα, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τόλμα</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (forma jônica/ática de <span class=\"greek\">τόλμη</span>; Pind., Hdt.+; Diod S 18, 25, 1; SIG 709, 25 [107 a.C.]; POxy 1119, 8; PFlor 382, 48; LXX; Jos., Bell. 4, 424, Ant. 14, 474, Vi. 222; SibOr 4, 154; Just., D. 79, 2; Tat. 14, 1) audácia 1 Cl 30:8 (com <span class=\"greek\">θράσος</span> [como Socrat., Ep. 14, 1=p. 252 Malherbe], <span class=\"greek\">αὐθάδεια</span>).—DELG s.v. <span class=\"greek\">τόλμη</span>. M-M. s.v. <span class=\"greek\">τολμάω</span>. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολμάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τολμάω</span> imperf. <span class=\"greek\">ἐτόλμων</span>; fut. <span class=\"greek\">τολμήσω</span>; 1 aor. <span class=\"greek\">ἐτόλμησα</span>; inf. perf. <span class=\"greek\">τετολμηκέναι</span> (Just., D. 133) (v. <span class=\"greek\">τόλμα</span>; Hom.+) demonstrar ousadia ou resolução diante de perigo, oposição ou problema, ousar, dispor-se a (fazer algo)</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> com inf.</p><p class=\"entry-text\"><span class=\"greek\">α</span>. ousar, ter coragem, ser suficientemente corajoso <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀγαθοῦ</span> <span class=\"greek\">τάχα</span> <span class=\"greek\">τις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τολμᾷ</span> <span class=\"greek\">ἀποθανεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:7</a> (sobre estar disposto a morrer por um homem bom, cf. Ael. Aristid. 46 p. 346 D.; Vita Philonid. [s.v. <span class=\"greek\">τράχηλος</span>]). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:14</a>. Empregado principalmente com uma negativa (TestAbr B 4 p. 109, 1 [Stone p. 66]; Jos., Ant. 20, 7 <span class=\"greek\">ἀντιλέγειν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐτόλμων</span>; Just., A I, 19, 2 e D. 33, 1) <span class=\"greek\">οὐδὲ</span> <span class=\"greek\">ἐτόλμησέν</span> <span class=\"greek\">τις</span> <span class=\"greek\">ἐπερωτῆσαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:46</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:34</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.40\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:40</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 21:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:13</a>. <span class=\"greek\">Μωϋσῆς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐτόλμα</span> <span class=\"greek\">κατανοῆσαι</span> Moisés não se atrevia a olhar (para aquilo) 7:32.</p><p class=\"entry-text\"><span class=\"greek\">β</span>. dispor-se, atrever-se (Theognis 1, 377 Zeus dispõe-se a incluir pecadores e justos no mesmo destino; ‘A Tragédia’ em Simplicius In Epict. p. 95, 42 <span class=\"greek\">τολμῶ</span> <span class=\"greek\">κατειπεῖν</span>=não hesito em dizer claramente; Himerius, Or. 20, 3 <span class=\"greek\">λέγειν</span> <span class=\"greek\">τ</span>.; 3 Macc 3:21; TestAbr B 6 p. 110, 12 [Stone p. 68]; TestJob 24, 7; Philo, Somn. 1, 54; Jos., C. Ap. 1, 318; Just., A I, 61, 11) <span class=\"greek\">τολμᾷ</span> <span class=\"greek\">τις</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">κρίνεσθαι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀδίκων</span>; algum de vós se atreve a litigar perante os injustos? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:1</a> (<span class=\"greek\">κρίνω</span> 5a<span class=\"greek\">β</span>). Com uma negativa (TestAbr B 4 p. 109, 1 [Stone p. 66]; GrBar 12:6; Just., A II, 3, 6 e D. 112, 4) <span class=\"greek\">οὐ</span> <span class=\"greek\">τολμήσω</span> <span class=\"greek\">τι</span> <span class=\"greek\">λαλεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:18</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 10:12</a>; Jd 9.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> abs. ser corajoso (Job 15:12) <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἄν</span> <span class=\"greek\">τις</span> <span class=\"greek\">τολμᾷ</span>, … <span class=\"greek\">τολμῶ</span> <span class=\"greek\">κἀγώ</span> seja o que for que outro ouse fazer, … também posso dispor-me (a fazer o mesmo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:21</a>. <span class=\"greek\">τολμῆσαι</span> <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> demonstrar coragem ou ousadia para com alguém ou contra alguém (En 7:4) 10:2. <span class=\"greek\">τολμήσας</span> <span class=\"greek\">εἰσῆλθεν</span> tomou coragem e entrou <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:43</a>; GJs 24:2 (cf. Plut., Camillus 140 [22, 6] <span class=\"greek\">τολμήσας</span> <span class=\"greek\">παρέστη</span>).—DELG s.v. <span class=\"greek\">τόλμη</span>. B. 1149. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολμηρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τολμηρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">τόλμη</span>; Eur., Thu. et al.; Sir 8:15; 19:3; JosAs 23:7 cod. A 17, 7 [p. 67, 5 Bat.]; Jos., Ant. 1, 113; 14, 165; Just.) ousado, atrevido, audaz, adv. <span class=\"greek\">τολμηρῶς</span> (Thu. 3, 74, 1; 83, 3; X. et al.; Mitt-Wilck. I/2, 461, 25 [III d.C.]). Comp. <span class=\"greek\">τολμηρότερος</span> (Isocr. 14, 8 Bl. e frequentemente; Sir 19:2; Philo, Op. M. 170): seus advérbios, <span class=\"greek\">τολμηροτέρως</span> Ro 15:15 v.l. e <span class=\"greek\">τολμηρότερον</span> (Thu. 4, 126, 4; Polyb. 1, 17, 7) Ro 15:15, ambos=com certa ousadia.—DELG s.v. <span class=\"greek\">τόλμη</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολμηροτέρως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τολμηροτέρως</span> v. <span class=\"greek\">τολμηρός</span>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τολμητής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τολμητής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">τόλμη</span>; Thu. 1, 70, 3; Plut.; Lucian; Philo, De Jos. 222; Jos., Bell. 3, 475) pessoa ousada, audaz <span class=\"greek\">τολμηταὶ</span> <span class=\"greek\">αὐθάδεις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:10</a> (sobre o campo semântico, cf. Reader, Polemo p. 296f).—DELG s.v. <span class=\"greek\">τόλμη</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τομός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τομός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">τέμνω</span>; Soph., Pla.+) relativo a possuir a capacidade de cortar eficazmente, cortante, afiado comp. <span class=\"greek\">τομώτερος</span> (PSI 624, 1 [III a.C.]) em linguagem figurada a respeito da palavra de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:12</a> (cf. Lucian, Tox. 11; Ps.-Phoc. 124 <span class=\"greek\">ὅπλον</span> <span class=\"greek\">τοι</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">ἀνδρὶ</span> <span class=\"greek\">τομώτερόν</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">σιδήρου</span>).—DELG s.v. <span class=\"greek\">τέμνω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόνος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τόνος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">τείνω</span> ‘estender’; Aeschyl., Hdt. et al.; Philo; Jos., Bell. 6, 162) primariamente ‘estiramento, tensão’, em nossa literatura somente em sentido fig. força, qualidade duradoura (Plut., Brut. 999 [34, 3] <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀργῆς</span>) <span class=\"greek\">ὁ</span> <span class=\"greek\">φόβος</span> <span class=\"greek\">αὐτοῦ</span> (o diabo) <span class=\"greek\">τόνον</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔχει</span>=o temor do diabo não impõe tensão alguma à pessoa Hm 12, 4, 7.—DELG s.v. <span class=\"greek\">τανυ</span>-E.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόξον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τόξον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Hom.+; inscrições, papiros, LXX; En; PsSol 17:33; TestAbr B 14 p. 118, 22 [Stone p. 84]; TestJud; SibOr 3, 730; Jos., Ant. 1, 103; Ar. 11, 1) o arco como arma do arqueiro (Hecataeus: 264 Fgm. 21, 203 Jac. [em Jos., C. Ap. 1, 203]; TestJud 3:3; 7:5; 9:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:2</a> (AKerkeslager, JBL 112, ’93, 116–21: o cavaleiro do cavalo branco, imagem negativa da falsa realeza messiânica).—B. 1388. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοξότης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοξότης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom. et al.; inscrições, papiros, JosAs, Joseph.) arqueiro AcPl Ha 5, 6.—DELG s.v. <span class=\"greek\">τόξον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοπάζιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοπάζιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Athenodorus [I a.C.]: 746 Fgm. 4, 5 Jac. [em Clem. Alex., Protr. 4, 48, 5]; Diod S 3, 39, 5; Strabo 16, 4, 6; Ex 28:17; 36:17; Job 28:19; Ps 118:127; Ezk 28:13) topázio, pedra preciosa de amarelo brilhante, mais ou menos transparente (Michel Psellus, em Lapidaires p. 204, linha 7 <span class=\"greek\">λίθο</span> <span class=\"greek\">διαφανή</span>), na antiguidade frequentemente transformada em selos e gemas; embora talvez seja o crisólito amarelo-dourado, de maior valor, que se tem em vista <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:20</a>.—Quanto à literatura, v. s.v. <span class=\"greek\">ἀμέθυστος</span>.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοποθεσία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοποθεσία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">τόπος</span>, <span class=\"greek\">θέσις</span> [<span class=\"greek\">τίθημι</span>]; Diod S, Ptolem. et al.; papiros) disposição ordenada numa área, posicionamento <span class=\"greek\">αἱ</span> <span class=\"greek\">τοποθεσίαι</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">ἀγγελικαί</span> provavelmente se refere ao posicionamento celestial das hostes angélicas, as posições/hierarquias angélicas ITr 5:2 (cf. o posicionamento dos anjos em Rv; Vett. Val. 42, 12 a respeito da disposição dos corpos celestes).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τόπος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τόπος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Aeschyl.+) primariamente ‘lugar, posição, região’.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> área de qualquer tamanho, geralmente especificada como lugar de habitação</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> área geográfica habitada: lugar, a respeito de cidade, aldeia etc. (Manetho: 609 Fgm. 10, 238 Jac.; em Jos., C. Ap. 1, 238; Diod S 1, 15, 6; 2, 13, 6; 13, 64, 7; Jos., C. Ap. 1, 86; 2, 34) <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τόπου</span> <span class=\"greek\">ἐκείνου</span> (cf. Gen 29:22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:35</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:11</a> (a respeito dos habitantes); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:37</a>; 10:1 (com <span class=\"greek\">πόλις</span> como em 2 Ch 34:6; Jos., C. Ap. 2, 115); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:3</a>; 27:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:17</a> (v. <span class=\"greek\">πλέω</span>). <span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">τόπῳ</span> em todo lugar onde vivem pessoas ou cristãos (cf. Diod S 13, 22, 3 <span class=\"greek\">εἰς</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τόπον</span>; Mal 1:11; TestDan 6:7; ParJer 5:32; Just., D. 41, 3, e sobre o exagero no estilo epistolar PLond III, 891, 9 p. 242 [IV d.C., cristão] <span class=\"greek\">ἡ</span> <span class=\"greek\">εὐφημία</span> <span class=\"greek\">σου</span> <span class=\"greek\">περιεκύκλωσεν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κόσμον</span> <span class=\"greek\">ὅλον</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:16</a> v.l.; MPol 19:1; AcPl Ha 6, 5 e 15. Também <span class=\"greek\">κατὰ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τόπον</span> MPol ins <span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">τόπῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">χρόνῳ</span> D 14:3. Talvez seja aqui que se deva incluir <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔθνος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.48\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:48</a> (o siríaco sinaítico e Chrysost. vol. VIII 386e entendem <span class=\"greek\">τόπ</span>. como Jerusalém [cf. 2 Macc 3:2, 12]; mas v. 1b abaixo). <span class=\"greek\">ἐν</span> <span class=\"greek\">ποίῳ</span> <span class=\"greek\">τόπῳ</span> onde AcPl Ha 6, 12; sem <span class=\"greek\">ἐν</span> Hv 1:7 Joly. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἕτερον</span> <span class=\"greek\">τόπον</span> para outro lugar (Dio Chrys. 70 [20], 2; Plut., Mor. 108d) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:17</a>. Cf. AFridrichsen, Kgl. Hum. Vetensk. Samf. i. Uppsala, Årsbok ’43, 28–30.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> estrutura habitada: espaço, lugar, edifício etc. (Diod S 20, 100, 4 <span class=\"greek\">τόποι</span>=edifícios; POslo 55, 10 [c. 200 d.C.]; 1 Km 24:23; 2 Ch 25:10) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:31</a> (Stephan. Byz. s.v. <span class=\"greek\">Τρεμιθοῦς</span>: o <span class=\"greek\">τόπος</span> estremece à <span class=\"greek\">παρουσία</span> de Afrodite). Especialmente a respeito de um templo (2 Macc 5:17–20 [com <span class=\"greek\">ἔθνος</span>]; 10:7; 3 Macc 1:9ab al.; EpArist 81) talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.48\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:48</a> (v. 1a acima; o mesmo problema surge a respeito de <span class=\"greek\">τόπος</span> PLond 2710 recto, 6: HTR 29, ’36, 40; 45f.—<span class=\"greek\">τ</span>. a respeito de um templo Mitt-Wilck. I/2, 94, 20 [início de II d.C.]; Jos., Ant. 16, 165); <span class=\"greek\">τόπος</span> <span class=\"greek\">ἅγιος</span> (cf. Is 60:13; 2 Macc 1:29; 2:18; 8:17) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:13</a>; 21:28b.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> porção de uma área maior: lugar, localização (Diod S 2, 7, 5 <span class=\"greek\">τόπος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span>=o lugar em que se encontra a cidade; Just., D. 40, 2 <span class=\"greek\">ὁ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">Ἰερουσαλήμ</span>) <span class=\"greek\">ἔρημος</span> <span class=\"greek\">τόπος</span> (<span class=\"greek\">ἔρημος</span> 1a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:13</a>; cf. v. 15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:35</a>; 6:31f, 35; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:42</a>; 9:12; GJs 17:3. Pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:45</a>. <span class=\"greek\">πεδινός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:17</a>. <span class=\"greek\">κρημνώδης</span> Hv 1, 1, 3; Hs 6, 2, 6. <span class=\"greek\">καλός</span> v 3, 1, 3b. <span class=\"greek\">τόπος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀγροῦ</span> um lugar no campo 2, 1, 4; 3, 1, 3a; <span class=\"greek\">τοῦ</span> <span class=\"greek\">σπηλαίου</span> GJs 19:2 (cf. Just., D. 70, 1; 78, 6). Cf. Hv 2, 1, 1; Hs 6, 2, 4. Sobre <span class=\"greek\">τόπος</span> <span class=\"greek\">διθάλασσος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:41</a> v. <span class=\"greek\">διθάλασσος</span>. Cf. <span class=\"greek\">τραχεῖς</span> <span class=\"greek\">τόποι</span> lugares rochosos v. 29. <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">ὅπου</span> (TestAbr B 10 p. 114, 13 [Stone p. 76]; ParJer 7:32; ApcMos 33; Just., D. 78, 8) o lugar onde <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:20</a>; 6:23; 10:40; 11:30; 19:20, 41. <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">ἔνθα</span> GPt 13:56 (Just., A I, 19, 8; Mel., HE 4, 26, 14). <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἕστηκας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:33</a> (cf. Ex 3:5). O dat. em lugar de <span class=\"greek\">εἰς</span> com acus. (B-D-F §199) <span class=\"greek\">ποίῳ</span> <span class=\"greek\">τόπῳ</span> <span class=\"greek\">ἀπῆλθεν</span> Hv 4, 3, 7. <span class=\"greek\">ἐν</span> <span class=\"greek\">παντὶ</span> <span class=\"greek\">τόπῳ</span> em todo lugar (em Jerusalém) 1 Cl 41:2. Combinado com um nome <span class=\"greek\">εἰς</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">λεγόμενον</span> <span class=\"greek\">Γολγοθᾶ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:33a</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Γολγοθᾶν</span> <span class=\"greek\">τόπον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:22a</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 16:16</a>. Com gen.: <span class=\"greek\">κρανίου</span> <span class=\"greek\">τόπος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:33b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:22b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:17</a> (v. <span class=\"greek\">κρανίον</span>). <span class=\"greek\">τόπος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καταπαύσεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.49\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:49</a>; B 16:2 (ambos Is 66:1; v. <span class=\"greek\">κατάπαυσις</span> 1).—Pleonástico <span class=\"greek\">ἐν</span> <span class=\"greek\">τόπῳ</span> <span class=\"greek\">χωρίου</span> <span class=\"greek\">Ῥωμαίων</span> IRo insc. (v. <span class=\"greek\">τύπος</span> 6c, final).—Lugar (determinado), ponto (particular), cenário <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:32</a>; 19:5; 22:40; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:13</a>; 6:10. <span class=\"greek\">ἐκεῖνον</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> Papias (3:3) (Just., D. 3, 1 <span class=\"greek\">ἐκείνου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τόπου</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓓ</span> pl. regiões, distritos (Diod S 4, 23, 2; 13, 109, 2; Artem. 2, 9 p. 92, 28; PHib 66, 2; PTebt 281, 12 al.; EpArist 22; Jos., C. Ap. 1, 9) <span class=\"greek\">ἄνυδροι</span> <span class=\"greek\">τόποι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:43</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:24</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἀνατολικοὶ</span> <span class=\"greek\">τόποι</span> o oriente 1 Cl 25:1. <span class=\"greek\">κατὰ</span> <span class=\"greek\">τόπους</span> em diversas regiões (<span class=\"greek\">κατά</span> B 1a) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:11</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἀσίαν</span> <span class=\"greek\">τόπους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:2</a> (Antig. Car. 172 <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">τόπους</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓔ</span> morada: lugar, espaço para viver, permanecer, sentar-se etc. (UPZ 146, 31; 37 [II a.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:14</a>. <span class=\"greek\">ἔτι</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">ἐστίν</span> ainda há lugar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:22</a> (Epict. 2, 13, 10 <span class=\"greek\">ποῦ</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">τόπος</span>; onde ainda há lugar?; Ath. 8, 4 <span class=\"greek\">τίς</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">τόπος</span>;). <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἦν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">καταλύματι</span> 2:7. <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔνι</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀπόκρυφος</span> não havia esconderijo GJs 22:3. <span class=\"greek\">ἔχειν</span> <span class=\"greek\">τόπον</span> ter (um) lugar Rv 12:6; cf. IPhld 2:2; Hv 3, 5, 5; 3, 7, 5; 3, 9, 5; m 12, 5, 4ab. <span class=\"greek\">ἑτοιμάσαι</span> <span class=\"greek\">τινὶ</span> <span class=\"greek\">τόπον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:2f</a> (cf. Rv 12:6). <span class=\"greek\">δὸς</span> <span class=\"greek\">τούτῳ</span> <span class=\"greek\">τόπον</span> dá lugar a esta pessoa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:9a</a> (Epict 4, 1, 106 <span class=\"greek\">δὸς</span> <span class=\"greek\">ἄλλοις</span> <span class=\"greek\">τόπον</span>=dá lugar a outros). <span class=\"greek\">ὁ</span> <span class=\"greek\">ἔσχατος</span> <span class=\"greek\">τόπος</span> (<span class=\"greek\">ἔσχατος</span> 1 e 3) vv. 9b e 10 (sobre <span class=\"greek\">τόπος</span>=‘um lugar para sentar-se’, cf. Jos., Ant. 12, 210 <span class=\"greek\">οἱ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">τόπους</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀξίαν</span> <span class=\"greek\">διανέμοντες</span>; Epict. 1, 25, 27; Paus. Attic. <span class=\"greek\">α</span>, 128 <span class=\"greek\">τόπος</span> a respeito de um assento num teatro; Diog. L. 7, 22 <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πτωχῶν</span> <span class=\"greek\">τόπ</span>.=o lugar em que os pobres se sentavam [no auditório em que Zenão, o estoico, ensinava]; Eunap. p. 21; IPergamon 618, v. Dssm., NB 95 [BS 267]). <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀγγέλων</span> <span class=\"greek\">ἐστίν</span> seu lugar é com os anjos Hs 9, 27, 3. Sobre <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀναπληρῶν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἰδιώτου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:16</a> v. <span class=\"greek\">ἀναπληρόω</span> 4 (para <span class=\"greek\">τόπος</span>=‘posição’ v. TestAbr B 4 p. 108, 20 [Stone p. 64] <span class=\"greek\">ἕκαστος</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">αὐτοῦ</span>; Philo, Somn. 1, 238; Jos., Ant. 16, 190 <span class=\"greek\">ἀπολογουμένου</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">λαμβάνων</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓕ</span> localização habitual de algo: o lugar em que algo se encontra, ou ao menos deveria ou poderia encontrar-se; com gen. da coisa em questão <span class=\"greek\">ἀπόστρεψον</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μάχαιράν</span> <span class=\"greek\">σου</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">αὐτῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.52\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:52</a> (em referência à bainha). <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἥλων</span> o lugar em que estiveram os cravos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.25\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:25</a> v.l. (Theodor. Prodr. 9, 174 ‘a marca’ de feridas por arranhaduras). <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">αὐτῆς</span> seu lugar, a respeito do lugar do candelabro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:5</a>. Cf. 6:14. <span class=\"greek\">τόπος</span> <span class=\"greek\">οὐχ</span> <span class=\"greek\">εὐρέθη</span> <span class=\"greek\">αὐτοῖς</span> já não havia lugar para eles (Da 2:35 Theod.—Ps 131:5) 20:11; cf. 12:8. Emprego não literal <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">δευτέρας</span> (subentende-se <span class=\"greek\">διαθήκης</span>) <span class=\"greek\">ἐζητεῖτο</span> <span class=\"greek\">τόπος</span> não se teria procurado ocasião para uma segunda (aliança) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:7</a>. Sobre <span class=\"greek\">τὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὑπακοῆς</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">ἀναπληρώσαντες</span> 1 Cl 63:1 v. <span class=\"greek\">ἀναπληρόω</span> 3. <span class=\"greek\">ἀποκατασταθήσῃ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">σου</span> (cod. A <span class=\"greek\">οἶκον</span>) serás restituído às tuas circunstâncias anteriores Hs 7:6.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓖ</span> lugar transcendente: especialmente a respeito do lugar ao qual o destino final de alguém o conduz. A respeito do lugar de salvação (Tob 3:6 <span class=\"greek\">ὁ</span> <span class=\"greek\">αἰώνιος</span> <span class=\"greek\">τόπος</span>; TestJob 49:2 <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὑψηλοῦ</span> <span class=\"greek\">τόπου</span>; JosAs 22:9 <span class=\"greek\">τῆς</span> <span class=\"greek\">καταπαύσεως</span>; ApcSed 16:5 <span class=\"greek\">ἀναψύξεως</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀναπαύσεως</span>; Ath. 22, 7 <span class=\"greek\">οὐράνιον</span> <span class=\"greek\">τόπον</span>): 2 Cl 1:2. <span class=\"greek\">πορεύεσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὀφειλόμενον</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δόξης</span> 1 Cl 5:4. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὀφειλόμενον</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> Pol 9:2. <span class=\"greek\">ὁ</span> <span class=\"greek\">ἅγιος</span> <span class=\"greek\">τόπος</span> 1 Cl 5:7. Cf. 44:5; B 19:1.—<span class=\"greek\">ὁ</span> <span class=\"greek\">ἴδιος</span> <span class=\"greek\">τόπος</span> pode ser neutro (PGM 4, 3123; Cyranides p. 120, 6), um lugar para onde alguém está destinado a ir IMg 5:1. Mas a expressão também pode adquirir seu significado específico a partir do contexto. A respeito de um lugar de tormento ou de mal (TestAbr A 13 p. 93, 12 [Stone p. 34; seguido de <span class=\"greek\">κολαστήριον</span>]; TestAbr B 10 p. 114, 10 [Stone p. 76]; Iambl., Vi. Pyth. 30. 178 <span class=\"greek\">ὁ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀσεβῶν</span> <span class=\"greek\">τ</span>. Proclus sobre Pla., Cratylus p. 72, 7 Pasqu.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:25b</a>; cf. Hs 9, 4, 7; 9, 5, 4; 9, 12, 4. Com gen. <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασάνου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:28</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> ponto específico de referência em um livro, lugar, passagem (Polyb. 12, 25f, 1; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 9, 8 [=p. 18, 5 V.]; 1 Esdr 6:22 v.l.; Philo, De Jos. 151; Jos., Ant. 14, 114; Just., D. 112, 4; cf. <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 3, 5 [=p. 8, 6 V.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:17</a>. Cf. 1 Cl 8:4; 29:3; 46:3.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> posição ocupada num grupo para o desempenho de alguma responsabilidade, posição, cargo (Diod S 1, 75, 4 num órgão judicial; 19, 3, 1 a respeito de um quiliarca [comandante de 1,000 homens]; Ps.-Callisth. 2, 1, 5 o <span class=\"greek\">τόπος</span> da sacerdotisa-profetisa; inscrições [<span class=\"greek\">ΕΛΛΗΝΙΚΑ</span> 7, ’34, p. 179 linha 50, 218 a.C.]; papiros; Dssm., NB 95 [BS 267]) <span class=\"greek\">λαβεῖν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">διακονίας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:25a</a>. Para <span class=\"greek\">ἐκδίκει</span> <span class=\"greek\">σου</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> IPol 1:2 v. <span class=\"greek\">ἐκδικέω</span> 3. <span class=\"greek\">τόπος</span> <span class=\"greek\">μηδένα</span> <span class=\"greek\">φυσιούτω</span> que uma posição elevada não ensoberbeça ninguém ISm 6:1. <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἱερεῦσιν</span> <span class=\"greek\">ἴδιος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> <span class=\"greek\">προστέτακται</span> um cargo especial foi atribuído aos sacerdotes 1 Cl 40:5.—44:5. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ζαχαρίου</span> GJs 24:4.</p><p class=\"entry-text\"><span class=\"sense-number\">④</span> circunstância favorável para fazer algo, possibilidade, oportunidade, ocasião (Just., D. 36, 2 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἁρμόζοντι</span> <span class=\"greek\">τόπῳ</span> no ponto apropriado da discussão; com gen. Polyb. 1, 88, 2 <span class=\"greek\">τόπος</span> <span class=\"greek\">ἐλέους</span>; Heliod. 6, 13, 3 <span class=\"greek\">φυγῆς</span> <span class=\"greek\">τόπος</span>; 1 Macc 9:45) <span class=\"greek\">τόπον</span> <span class=\"greek\">ἀπολογίας</span> <span class=\"greek\">λαβεῖν</span> ter oportunidade de defender-se <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:16</a> (cf. Jos., Ant. 16, 258 <span class=\"greek\">μήτ</span>’ <span class=\"greek\">ἀπολογίας</span> <span class=\"greek\">μήτ</span>’ <span class=\"greek\">ἐλέγχου</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">ἐχόντων</span>). <span class=\"greek\">μετανοίας</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">εὑρεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:17</a>; <span class=\"greek\">διδόναι</span> (cf. Wsd 12:10) 1 Cl 7:5. Na última passagem, as pessoas a quem se concede a oportunidade são acrescentadas no dat. (cf. Plut., Mor. 62d; Mitt-Wilck. I/2, 14 III, 15 [I d.C.] <span class=\"greek\">βασιλεῖ</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">διδόναι</span>=dar a um rei uma oportunidade; Sir 4:5). <span class=\"greek\">μηδὲ</span> <span class=\"greek\">δίδοτε</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">διαβόλῳ</span> não deis ao diabo ocasião de exercer sua influência <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:27</a>. <span class=\"greek\">δότε</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὀργῇ</span> dai à ira (de Deus) oportunidade de realizar seu propósito Ro 12:19 (sobre <span class=\"greek\">ὀργῇ</span> <span class=\"greek\">διδόναι</span> <span class=\"greek\">τόπον</span> cf. Plut., Mor. 462b; cf. também <span class=\"greek\">δὸς</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">νόμῳ</span> Sir 19:17. Sobre Ro 12:19 v. ESmothers, CBQ 6, ’44, 205–15, com referências ali; Goodsp., Probs. 152–54). <span class=\"greek\">τόπον</span> <span class=\"greek\">ἔχειν</span> ter oportunidade (de realizar o trabalho de um apóstolo) 15:23.</p><p class=\"entry-text\"><span class=\"sense-number\">⑤</span> expressão idiomática: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">τόπῳ</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐρρέθη</span> <span class=\"greek\">αὐτοῖς</span> …, <span class=\"greek\">ἐκεῖ</span> <span class=\"greek\">κληθήσονται</span> (=LXX Hos 2:1) provavelmente deve ser traduzido em vez de lhes ser dito …, ali serão chamados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:26</a> (cf. Hos 2:1 <span class=\"hebrew\">בִּמְקוֹם</span> <span class=\"hebrew\">אֲשֶׁר</span> ‘em vez de’ v. HWolff, Hosea [Hermeneia] ’74, 27; Achmes 207, 17 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">τόπῳ</span> <span class=\"greek\">ἐκείνῳ</span>=em vez disso).—DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοσοῦτος, αύτη, οῦτον</h1><div class=\"entry-meta\"><span>adjetivo correlativo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοσοῦτος</span>, <span class=\"greek\">αύτη</span>, <span class=\"greek\">οῦτον</span> (esta forma do neutro predomina no grego ático, também Appian, Bell. Civ. 3, 43 §177; LXX, GrBar; Jos., C. Ap. 1, 226; 2, 176; Hb 7:22 v.l.; 12:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:16</a> v.l.; 1 Cl 1:1; MPol 2:2; Hm 5, 1, 5; Just., Ath.) e <span class=\"greek\">οῦτο</span> (Clearchus, Fgm. 48 W.: Diod S 1, 58, 4; PCairZen 367, 38; PMich I [Zen] 28, 17 [III a.C.]; Num 15:5; 1 Macc 3:17; Hb 7:22; 1 Cl 45:7; Just., A I, 56, 2) adj. correlativo (Hom.+) ‘tão grande, tão volumoso, tão distante, tanto, tão forte’ etc.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> relativo a um número elevado indefinido de entidades ou acontecimentos, tantos, pl.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> com um substantivo (Just., D. 75, 4 <span class=\"greek\">ἐν</span> <span class=\"greek\">τοσαύταις</span> <span class=\"greek\">μορφαῖς</span>) tantos <span class=\"greek\">ἄρτοι</span> <span class=\"greek\">τοσοῦτοι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:33</a> (seguido de <span class=\"greek\">ὥστε</span>). <span class=\"greek\">ἔτη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:29</a>. <span class=\"greek\">σημεῖα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.37\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:37</a>. Cf. 21:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:10</a> (v. <span class=\"greek\">τυγχάνω</span> 2b); Hs 6, 4, 4.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> sem substantivo <span class=\"greek\">τοσοῦτοι</span> tantas pessoas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:9</a>; AcPl Ha 7, 21 (a menos que este caso se inclua em 2).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> relativo a um grau elevado de quantidade, tanto, tão grande</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> com um substantivo <span class=\"greek\">τοσοῦτος</span> <span class=\"greek\">ὄχλος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:33b</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">τοσοῦτος</span> <span class=\"greek\">πλοῦτος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:17</a> (leitura erasmiana, e somente aqui com o art.; v. B-D-F §274; Rob. 771). <span class=\"greek\">τοσοῦτον</span> <span class=\"greek\">μέλι</span> tão grande quantidade de mel Hm 5, 1, 5. <span class=\"greek\">τοσαύτη</span> <span class=\"greek\">ἔκρυσις</span> Papias (3:2). A respeito de espaço <span class=\"greek\">μῆκος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:16</a> v.l. A respeito de tempo <span class=\"greek\">χρόνος</span> (PLond I, 42, 23 p. 30 [168 a.C.]; POxy 1481, 2; ParJer 5:18; Jos., Bell. 1, 665; 2, 413; Dio Chrys. 74, 18b; Ath. 17, 3) por tanto tempo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:7</a>. <span class=\"greek\">τος</span>. <span class=\"greek\">διαφορά</span> tão grande diferença MPol 16:1. Referindo-se ao precedente <span class=\"greek\">ὅσα</span>: <span class=\"greek\">τοσοῦτον</span> <span class=\"greek\">βασανισμόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:7</a>. Para <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:1</a> v. 3 abaixo.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> sem substantivo, pl. <span class=\"greek\">τοσαῦτα</span> a respeito de quantidade, tanto (Socrat., Ep. 14, 6 [p. 256, 11 Malherbe]; Just., D. 77, 1 <span class=\"greek\">τοιαῦτα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τοσαῦτα</span>) Hv 2, 1, 3. <span class=\"greek\">ἡμαρτηκὼς</span> <span class=\"greek\">τοσαῦτα</span> visto que pequei tantas vezes Hm 9:1. Alguns entendem igualmente em sentido quantitativo <span class=\"greek\">τοσαῦτο</span> <span class=\"greek\">ἐπάθετε</span>; experimentastes tanto? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:4</a>, mas sobre este caso e Hm 9:1 v. 3b.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> relativo a um grau elevado de qualidade ou à falta dela, tão grande/forte, a tal ponto etc.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> com um substantivo e em sentido positivo <span class=\"greek\">πίστις</span> fé tão forte como esta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:9</a>. <span class=\"greek\">ἔλεος</span> 2 Cl 3:1. <span class=\"greek\">ζωή</span> 14:5. <span class=\"greek\">χρηστότης</span> 15:5. <span class=\"greek\">σπουδή</span> MPol 7:2. <span class=\"greek\">τάχος</span> 13:1. Seguido de <span class=\"greek\">ὥστε</span> (Ps.-Callisth. 3, 26, 7 p. 127, 6; Just., D. 30, 3) <span class=\"greek\">τος</span>. <span class=\"greek\">ἀπόνοια</span> 1 Cl 46:7. Seguido de <span class=\"greek\">ὡς</span> tão forte como MPol 15:2; tão forte que ApcPt 5:16 (Just., D. 132, 1). Provavelmente é aqui que se deve incluir <span class=\"greek\">τοσοῦτον</span> <span class=\"greek\">νέφος</span> <span class=\"greek\">μαρτύρων</span> tão grande nuvem de testemunhas (o ‘grande’ número sendo naturalmente qualificado pelas limitações literárias) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:1</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> sem substantivo e em sentido negativo, <span class=\"greek\">εἰς</span> <span class=\"greek\">τοσοῦτο</span>(<span class=\"greek\">ν</span>) seguido de gen. e <span class=\"greek\">ὥστε</span> a tal grau de (Andoc. 2, 7: <span class=\"greek\">εἰς</span> <span class=\"greek\">τοσοῦτον</span> <span class=\"greek\">ἦλθον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δυσδαιμονίας</span> … , <span class=\"greek\">ὥστε</span>; Pla., Apol. 13, 25e; Clearchus, Fgm. 48; Jos., Bell. 4, 317 <span class=\"greek\">εἰς</span> <span class=\"greek\">τος</span>. <span class=\"greek\">ἀσεβείας</span>, <span class=\"greek\">ὥστε</span>, C. Ap. 1, 226) 1 Cl 1:1; 45:7; MPol 2:2. <span class=\"greek\">τοσοῦτον</span> a ponto de que, a tal ponto que (GrBar 1:3; 8:3; Just., D. 90, 4) <span class=\"greek\">τὰ</span> <span class=\"greek\">βλέφαρα</span> … <span class=\"greek\">τοσοῦτον</span> <span class=\"greek\">ἐξοιδῆσαι</span> <span class=\"greek\">ὡς</span> as pálpebras (de Judas) ficaram tão inchadas que Papias (3:2) (com <span class=\"greek\">ὡς</span> como em Just., D. 121, 3). Talvez Hm 9:1 pertença aqui: pecados tão graves (v. 2b acima). Em sátira <span class=\"greek\">τοσαῦτα</span> <span class=\"greek\">ἐπάθετε</span>; tivestes experiências tão extraordinárias? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:4</a> (<span class=\"greek\">πάσχω</span> 1; outros incluem a passagem em 2b acima).</p><p class=\"entry-text\"><span class=\"sense-number\">④</span> relativo a uma extensão limitada, tanto e nada mais <span class=\"greek\">τοσούτου</span> (gen. de preço) por tanto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:8ab</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">⑤</span> relativo a um grau correlativo, tanto, quanto <span class=\"greek\">τοσούτῳ</span> com o comp., correspondente a <span class=\"greek\">ὅσῳ</span> tanto (maior, mais etc.) … do que ou quanto (X., Mem. 1, 3, 13; Ael. Aristid. 23, 55 K.=42 p. 786 D.; Just., D. 110, 4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:4</a>; 10:25 (<span class=\"greek\">τοσούτῳ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ὅσῳ</span> como em Ael. Aristid. 33 p. 616 D.; 46 p. 345; cf. X., Mem. 1, 4, 10); quanto mais … tanto mais 1 Cl 41:4; 48:6. <span class=\"greek\">τοσοῦτον</span> … <span class=\"greek\">ὅσον</span> tanto … quanto Papias (2:4) <span class=\"greek\">οὐ</span> … <span class=\"greek\">τοσοῦτόν</span> <span class=\"greek\">με</span> <span class=\"greek\">ὠφελεῖν</span> <span class=\"greek\">ὅσον</span> não o mesmo valor (probatório) que (Just., D. 1, 3; Ath. 15, 2). <span class=\"greek\">καθ</span>’ <span class=\"greek\">ὅσον</span> … <span class=\"greek\">κατὰ</span> <span class=\"greek\">τοσοῦτο</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:20–22</a>. <span class=\"greek\">τοσούτῳ</span> <span class=\"greek\">ἥδιον</span> … <span class=\"greek\">ἐπειδή</span> tanto mais de bom grado … visto que 1 Cl 62:3. <span class=\"greek\">τοσοῦτον</span>.—DELG s.v. <span class=\"greek\">τόσος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τότε</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τότε</span> (Hom.+) adv. correlativo (v. <span class=\"greek\">ὅτε</span> e <span class=\"greek\">ὁπότε</span>) de tempo, no NT particularmente predileto de Mt, que o emprega cerca de 90 vezes (AMcNeile, <span class=\"greek\">Τότε</span> in St. Matthew: JTS 12, 1911, 127f). Em Mk 6 vezes, Lk 15 vezes, Ac 21 vezes, J 10 vezes. Está ausente em Eph, Phil, Phlm, 1 Ti, 2 Ti, Tit, Js, 1 Pt, 1, 2 e 3J, Jd, Rv.</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> naquele tempo</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> a respeito do passado, então (Demetr.: 722 Fgm. 1, 2 e 11 Jac.; Jos., Ant. 7, 317; 15, 354; Just., A I, 31, 2; D. 60, 1f) <span class=\"greek\">τότε</span> <span class=\"greek\">ἐπληρώθη</span> então se cumpriu <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:17</a>; 27:9. <span class=\"greek\">εἶχον</span> <span class=\"greek\">τότε</span> <span class=\"greek\">δέσμιον</span> v. 16. Cf. 3:5. (Oposto a <span class=\"greek\">νῦν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:8</a>, 29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:26</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τότε</span> desde aquele tempo (PLond V, 1674, 21; 2 Esdr 5:16b; Ps 92:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:17</a>; 16:21; 26:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:16</a> (v. B-D-F §459, 3). Empregado como adj. com o art. precedente (Appian, Bell. Civ. 4, 30 §128 <span class=\"greek\">ἡ</span> <span class=\"greek\">τότε</span> <span class=\"greek\">τύχη</span>; Lucian, Imag. 17; Jos., Ant. 14, 481) <span class=\"greek\">ὁ</span> <span class=\"greek\">τότε</span> <span class=\"greek\">κόσμος</span> o mundo daquele tempo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:6</a> (PHamb 21, 9 <span class=\"greek\">ὁ</span> <span class=\"greek\">τότε</span> <span class=\"greek\">καιρός</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> a respeito do futuro, então (Just., A I, 52, 9, D. 50, 1; Socrat., Ep. 6, 10 [p. 238, 7 Malherbe]) <span class=\"greek\">τότε</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">δίκαιοι</span> <span class=\"greek\">ἐκλάμψουσιν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:43</a>. (Oposto a <span class=\"greek\">ἄρτι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:12ab</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> a respeito de qualquer tempo que satisfaça determinadas condições <span class=\"greek\">ὅταν</span> <span class=\"greek\">ἀσθενῶ</span>, <span class=\"greek\">τότε</span> <span class=\"greek\">δυνατός</span> <span class=\"greek\">εἰμι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:10</a>.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> para introduzir aquilo que segue no tempo (em desacordo com o grego anterior), então, em seguida (B-D-F §459, 2) <span class=\"greek\">τότε</span> <span class=\"greek\">Ἡρῴδης</span> <span class=\"greek\">λάθρᾳ</span> <span class=\"greek\">καλέσας</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">μάγους</span> então (depois de haver recebido uma resposta do conselho) Herodes convocou secretamente os magos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:7</a>. <span class=\"greek\">τότε</span> (=depois de seu batismo) <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ἀνήχθη</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἔρημον</span> 4:1. Cf. 2:16 (GJs 22:1); 3:13, 15; 4:5, 10f; 8:26; 12:22; 25:34–45 (cinco vezes); 26:65 e muito frequentemente; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:26</a>; 14:21; 21:10; 24:45; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:12</a>; 4:8; B 8:1; GJs 22:3. <span class=\"greek\">καὶ</span> <span class=\"greek\">τότε</span> (Just., D. 78, 5; 88, 3) e então <span class=\"greek\">καὶ</span> <span class=\"greek\">τότε</span> <span class=\"greek\">ἐάν</span> <span class=\"greek\">τις</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">εἴπῃ</span> e então, se alguém vos disser <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:21</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:23</a>; 16:27; 24:10, 14, 30ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:26f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:8</a>; 2 Cl 16:3. <span class=\"greek\">τότε</span> <span class=\"greek\">οὖν</span> (pois) então (TestJud 7:5; 9:7; TestIss 2:1; Just., D. 56, 19) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:14</a>; 19:1, 16; 20:8. <span class=\"greek\">εὐθέως</span> <span class=\"greek\">τότε</span> imediatamente depois <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:14</a>.—Com correlativos: <span class=\"greek\">ὅτε</span> (com aor.) … <span class=\"greek\">τότε</span> quando (isto ou aquilo aconteceu) … (então) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:26</a>; 21:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:16</a>; B 5:9. Também <span class=\"greek\">ὡς</span> (com aor.) … <span class=\"greek\">τότε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:10</a>; 11:6. <span class=\"greek\">ὅταν</span> (com subj. aor.) … <span class=\"greek\">τότε</span> quando (isto ou aquilo acontecer) … (então) (Just., D. 110, 1; cf. Diod S 11, 40, 3 <span class=\"greek\">τότε</span> … <span class=\"greek\">ὅταν</span> [com subj. aor.]=então … quando) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:16</a>; 25:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:35</a>; 21:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:28</a>, 54; 16:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:4</a>. <span class=\"greek\">ὅταν</span> (com subj. pres.) … <span class=\"greek\">τότε</span> quando … então (Jos., Bell. 6, 287) <span class=\"greek\">ὅταν</span> <span class=\"greek\">λέγωσιν</span> … <span class=\"greek\">τότε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:3</a>. Numa enumeração <span class=\"greek\">πρῶτον</span> … , <span class=\"greek\">καὶ</span> <span class=\"greek\">τότε</span> primeiro …, e então <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:24</a>; 7:5; 12:29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:10</a> v.l. IEph 7:2.—É colocado pleonasticamente (cf. Vett. Val. 211, 8) depois de <span class=\"greek\">μετά</span> e do acus. <span class=\"greek\">μετὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ψωμίον</span>, <span class=\"greek\">τότε</span> depois de (ele ter tomado) o pedaço de pão, (então) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:27</a>. Cf. Hv 2, 2, 4. Também depois do partic. <span class=\"greek\">διασωθέντες</span>, <span class=\"greek\">τότε</span> <span class=\"greek\">ἐπέγνωμεν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:1</a>. Igualmente em emprego pleonástico 6:11 D; 27:21; Hs 6, 5, 4.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοὐναντίον</h1><div class=\"entry-meta\"><span>expressão remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοὐναντίον</span> v. <span class=\"greek\">ἐναντίον</span> 2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοὔνομα</h1><div class=\"entry-meta\"><span>expressão remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοὔνομα</span> v. <span class=\"greek\">ὄνομα</span> 1a, final.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τοὐπίσω</h1><div class=\"entry-meta\"><span>expressão remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τοὐπίσω</span>=<span class=\"greek\">τὸ</span> <span class=\"greek\">ὀπίσω</span>; v. <span class=\"greek\">ὀπίσω</span> 1a<span class=\"greek\">α</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0360-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τουτέστιν</h1><div class=\"entry-meta\"><span>expressão remissiva</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τουτέστιν</span> v. <span class=\"greek\">εἰμί</span> 2c<span class=\"greek\">α</span> e, sobre a grafia, B-D-F §12, 3; 17; Rob. 207.—M-M.</p></section></article>"};
